#include <tests.h>
int depth;
void hop() { depth++; call_out("hop", 0); }
void fin() { ASSERT_EQ(10, depth); RELEASE_LATCH("q"); }
void do_tests() {
    mixed e = catch(throw(0));
    ASSERT_EQ(0, e);
    "/single/master"->expect_deferred_error("Nesting call_out(0) level limit exceeded");
    EXPECT_LATCH("q");
    call_out("hop", 0);
    call_out("fin", 1);
}
